 void assetTree(String key,File dst)throws IOException{String[] children=getAssets().list(key);if(children!=null&&children.length>0){dst.mkdirs();for(String c:children)assetTree(key+"/"+c,new File(dst,c));}else if(!dst.exists()){dst.getParentFile().mkdirs();try(InputStream in=getAssets().open(key);OutputStream out=new FileOutputStream(dst)){pipe(in,out,512L*1024*1024);}}}
 static String read(File f)throws IOException{try(InputStream in=new FileInputStream(f);ByteArrayOutputStream o=new ByteArrayOutputStream()){pipe(in,o,16*1024*1024);return o.toString("UTF-8");}}
 static long pipe(InputStream in,OutputStream out,long limit)throws IOException{byte[] buf=new byte[65536];long total=0;int n;while((n=in.read(buf))!=-1){total+=n;if(total>limit)throw new IOException("File too large");out.write(buf,0,n);}return total;}
 void write(File f,String data)throws IOException{f.getParentFile().mkdirs();try(OutputStream o=new FileOutputStream(f)){o.write(data.getBytes("UTF-8"));}}
 void message(String title,String body){new AlertDialog.Builder(this).setTitle(title).setMessage(body).setPositiveButton("OK",null).show();}
