 void parseTheme(){lx=.636f;ly=.185f;lw=.30f;lh=.63f;selector="#9B3F0D";try{
  File xml=new File(currentTheme,"theme.xml");if(!xml.exists())return;DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();try{f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);}catch(Exception ignored){}f.setExpandEntityReferences(false);Document d=f.newDocumentBuilder().parse(xml);NodeList ls=d.getElementsByTagName("textlist");for(int i=0;i<ls.getLength();i++){Element e=(Element)ls.item(i);if(!"gamelist".equals(e.getAttribute("name")))continue;String[]pos=value(e,"pos").trim().split("\\s+"),size=value(e,"size").trim().split("\\s+");float x=Float.parseFloat(pos[0]),y=Float.parseFloat(pos[1]),w=Float.parseFloat(size[0]),h=Float.parseFloat(size[1]);if(x>=0&&y>=0&&w>.1&&h>.1&&x+w<=1.01&&y+h<=1.01){lx=x;ly=y;lw=w;lh=h;}String col=value(e,"selectorColor");if(col.length()>=6)selector="#"+col.substring(0,6);break;}
 }catch(Exception ignored){}}
 String value(Element e,String tag){NodeList n=e.getElementsByTagName(tag);return n.getLength()>0?n.item(0).getTextContent():"";}
