 void updateList(){visible.clear();for(int i=0;i<catalog.length();i++){JSONObject j=catalog.optJSONObject(i);if(j!=null&&(selectedSystem.equals("All")||selectedSystem.equals(j.optString("system"))))visible.add(j);}list.setAdapter(new BaseAdapter(){public int getCount(){return visible.size();}public Object getItem(int p){return visible.get(p);}public long getItemId(int p){return p;}public View getView(int p,View recycled,android.view.ViewGroup parent){TextView t=recycled instanceof TextView?(TextView)recycled:new TextView(MainActivity.this);t.setText(visible.get(p).optString("title"));t.setTextSize(18);try{File font=new File(currentTheme,"assets/font.ttf");if(font.isFile())t.setTypeface(Typeface.createFromFile(font));}catch(Exception ignored){}t.setSingleLine(true);t.setEllipsize(android.text.TextUtils.TruncateAt.END);t.setPadding(14,12,8,12);t.setTextColor(Color.WHITE);return t;}});status.setText(visible.isEmpty()?"USB Games → choose roms folder":selectedSystem+" • "+visible.size()+" games • OK: Play • Hold OK: Core");}
 
 HashMap<String,String> coverMap(Uri tree,String parent,ArrayList<Row>rows){HashMap<String,String>map=new HashMap<>();for(Row row:rows)if(row.name.equalsIgnoreCase("gamelist.xml")){try(InputStream in=getContentResolver().openInputStream(DocumentsContract.buildDocumentUriUsingTree(tree,row.id))){DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();try{f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);}catch(Exception ignored){}Document d=f.newDocumentBuilder().parse(in);NodeList games=d.getElementsByTagName("game");for(int i=0;i<games.getLength();i++){Element g=(Element)games.item(i);String path=value(g,"path");String image=value(g,"image");if(image.isEmpty())image=value(g,"thumbnail");if(!image.isEmpty())map.put(new File(path).getName(),image.startsWith("./")?image.substring(2):image);}}catch(Exception ignored){}}return map;}
