 void showCover(JSONObject game){String cover=game.optString("cover"),key=game.optString("path")+game.optString("uri");selectedCover=key;if(cover.isEmpty()){try{preview.setImageBitmap(BitmapFactory.decodeStream(getAssets().open("loading.png")));}catch(Exception ignored){}return;}worker.execute(()->{Bitmap bitmap=null;try{Uri tree=Uri.parse(game.getString("tree"));String id=find(tree,game.getString("parent"),Rules.safeRelative(cover));Uri u=DocumentsContract.buildDocumentUriUsingTree(tree,id);BitmapFactory.Options opt=new BitmapFactory.Options();opt.inSampleSize=2;try(InputStream in=getContentResolver().openInputStream(u)){bitmap=BitmapFactory.decodeStream(in,null,opt);}}catch(Exception ignored){}final Bitmap image=bitmap;ui.post(()->{if(selectedCover.equals(key)&&image!=null&&preview!=null)preview.setImageBitmap(image);});});}

 void systems(){TreeSet<String>s=new TreeSet<>();s.add("All");for(int i=0;i<catalog.length();i++)s.add(catalog.optJSONObject(i).optString("system"));String[]a=s.toArray(new String[0]);new AlertDialog.Builder(this).setTitle("Systems").setItems(a,(d,n)->{selectedSystem=a[n];updateList();}).show();}
 void playVideo(SurfaceTexture s){releaseVideo();File file=media("video","background","assets/live-background.mp4");if(!file.exists()){texture.setVisibility(View.GONE);return;}try{player=new MediaPlayer();player.setDataSource(file.getAbsolutePath());Surface surface=new Surface(s);player.setSurface(surface);surface.release();player.setVolume(0,0);player.setLooping(true);player.setOnPreparedListener(p->p.start());player.setOnErrorListener((p,w,e)->{releaseVideo();texture.setVisibility(View.GONE);return true;});player.prepareAsync();}catch(Exception e){releaseVideo();texture.setVisibility(View.GONE);}}
 void releaseVideo(){if(player!=null){try{player.release();}catch(Exception ignored){}player=null;}}
